```redb
@include "std"

is_prime = do(int -> bool) {
    if (arg1 < 2) {
        return false
    }
    i = 2
    while (i * i <= arg1) {
        if (arg1 % i == 0) {
            return false
        }
        i = i + 1
    }
    return true
}

main() {
    writeln(is_prime(17))
    writeln(is_prime(18))
}
```

