-- Largest element in an array. O(n) time.
-- Returns MIN_INT64() for an empty array.

Signature: `(array<int> -> int)`

```redb
max_element = do(array<int> -> int) {
    mx = MIN_INT64()
    for (i in 0 to arg1.size() - 1) {
        if (arg1[i] > mx) {
            mx = arg1[i]
        }
    }
    return mx
}
```

Signature: `(double -> double)`

```redb
sqrt = do(double -> double) {
    if (arg1 <= 0.0) {
        return 0.0
    }

    guess = arg1 / 2.0
    i = 0
    while (i < 20) {
        guess = (guess + (arg1 / guess)) / 2.0
        i = i + 1
    }
    return guess
}
```
